{"command": "python3 -c "
import cv2, numpy as np

f = 256.0
H = 1.55

for idx in [1, 2, 3, 4]:
    img = cv2.imread(f'/work/observations/obs_000{idx}.png')
    col = img[:, 256]
    for v in range(510, 0, -1):
        if np.mean(col[v]) > 240 and np.mean(col[v+1]) < 200:
            dist = f * H / (v - 256.0)
            print(f'obs_{idx}: wall base at v={v}, distance={dist:.2f} m')
            break
"", "description": "Compute wall distances from origin"}

